import { test, expect } from '@playwright/test';

test.describe('Reading Order Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should have correct heading hierarchy without skipped levels', async ({ page }) => {
    const headings = await page.getByRole('heading').all();

    let previousLevel = 0;
    for (const heading of headings) {
      const level = parseInt(await heading.evaluate(el => el.tagName.charAt(1)));

      // Heading level should not skip more than one level
      expect(level - previousLevel).toBeLessThanOrEqual(1);
      previousLevel = level;
    }
  });

  test('should have logical tab order matching visual order', async ({ page }) => {
    const focusableElements = await page.locator('a, button, input, select, textarea, [tabindex]').all();

    expect(focusableElements.length).toBeGreaterThan(0);

    // Verify all focusable elements have valid tabindex or are naturally focusable
    for (const element of focusableElements) {
      const tabindex = await element.getAttribute('tabindex');
      const role = await element.getAttribute('role');
      const tagName = await element.evaluate(el => el.tagName.toLowerCase());

      // Either naturally focusable or has valid tabindex
      const isNaturallyFocusable = ['a', 'button', 'input', 'select', 'textarea'].includes(tagName);
      const hasValidTabindex = tabindex === null || (parseInt(tabindex) >= -1);

      expect(isNaturallyFocusable || hasValidTabindex).toBeTruthy();
    }
  });

  test('should have descriptive link text that makes sense out of context', async ({ page }) => {
    const links = await page.getByRole('link').all();

    for (const link of links) {
      const text = await link.textContent();
      const ariaLabel = await link.getAttribute('aria-label');
      const title = await link.getAttribute('title');

      // Link should have meaningful text or aria-label
      const hasDescriptiveText = text && text.trim().length > 0 && text.trim() !== 'click here' && text.trim() !== 'read more';
      const hasAriaLabel = ariaLabel && ariaLabel.trim().length > 0;
      const hasTitle = title && title.trim().length > 0;

      expect(hasDescriptiveText || hasAriaLabel || hasTitle).toBeTruthy();
    }
  });

  test('should have proper landmark structure for page navigation', async ({ page }) => {
    // Check for main landmark
    const main = page.getByRole('main');
    await expect(main).toBeDefined();

    // Check for navigation landmark
    const nav = page.getByRole('navigation');
    const navCount = await nav.count();
    expect(navCount).toBeGreaterThanOrEqual(0);

    // Check for contentinfo landmark (footer)
    const contentinfo = page.getByRole('contentinfo');
    const contentinfoCount = await contentinfo.count();
    expect(contentinfoCount).toBeGreaterThanOrEqual(0);
  });

  test('should have form labels associated with inputs', async ({ page }) => {
    const inputs = await page.locator('input[type="text"], input[type="email"], input[type="password"], textarea, select').all();

    for (const input of inputs) {
      const inputId = await input.getAttribute('id');
      const ariaLabel = await input.getAttribute('aria-label');
      const ariaLabelledBy = await input.getAttribute('aria-labelledby');

      if (inputId) {
        // Check if there's a label associated with this input
        const label = page.locator(`label[for="${inputId}"]`);
        const labelCount = await label.count();

        // Either has associated label or aria-label or aria-labelledby
        const hasLabel = labelCount > 0 || ariaLabel || ariaLabelledBy;
        expect(hasLabel).toBeTruthy();
      } else {
        // If no ID, must have aria-label or aria-labelledby
        expect(ariaLabel || ariaLabelledBy).toBeTruthy();
      }
    }
  });

  test('should have proper list structure for grouped content', async ({ page }) => {
    const lists = await page.getByRole('list').all();

    for (const list of lists) {
      const listItems = list.getByRole('listitem');
      const itemCount = await listItems.count();

      // Lists should contain list items
      expect(itemCount).toBeGreaterThan(0);
    }
  });
});
